"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["15662"],{70252(e){e.exports=JSON.parse('{"id":"V4-127","slug":"conveyancing","term":"Conveyancing","also_known_as":[],"difficulty":"Intermediate","definition":"Conveyancing is the legal process of transferring ownership of a property from one person to another, carried out by a solicitor or licensed conveyancer.","explanation":["The term is used mainly in the United Kingdom, Australia and some other common law countries. In other countries, similar work may be done by lawyers, notaries, escrow agents or title companies.","The conveyancing process typically includes checking the property\u2019s legal title, carrying out searches with local authorities and other bodies to identify issues such as planning restrictions or flood risk, reviewing and negotiating the contract, handling the deposit and mortgage funds, completing the transfer and registering the new owner with the land registry.","For example, in England and Wales, when a buyer\u2019s offer is accepted, both buyer and seller instruct conveyancers, who work through the legal steps until contracts are exchanged, which makes the deal legally binding, and then completion, when the money is paid and the buyer receives the keys.","Conveyancing can take several weeks or months, and delays in chains of linked purchases are common. Conveyancing fees are part of the costs of buying or selling a property, along with taxes such as stamp duty and survey fees."],"note":"","total":1725,"prev":{"slug":"convexity","term":"Convexity"},"next":{"slug":"copayment","term":"Copayment"}}')}}]);